def count_no_of_ways(n, k):
    """Write a function to find out the number of ways of painting the fence such that at most 2 adjacent posts have the same color for the given fence with n posts and k colors."""
    if n < 0 or k < 0:
        raise ValueError("n and k must be non-negative")
    if n == 0:
        return 1
    if k == 0:
        return 0
    if n == 1:
        return k
    if n == 2:
        return k * k

    # For n > 2, adding a post gives the recurrence
    # f(n) = (k - 1) * (f(n - 1) + f(n - 2)): the new post can be a
    # different color than the previous post, or the same color as the
    # previous post when the two preceding posts differ.
    ways_for_n_minus_2 = k
    ways_for_n_minus_1 = k * k
    for _ in range(3, n + 1):
        ways = (k - 1) * (ways_for_n_minus_1 + ways_for_n_minus_2)
        ways_for_n_minus_2, ways_for_n_minus_1 = ways_for_n_minus_1, ways
    return ways_for_n_minus_1
